#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Pindahkan aset VIP/SVIP (±63MB) keluar dari APK -> di-host online dari repo GitHub (jsDelivr)
#  - app/src/main/assets/{vip,svip}  ->  remote-assets/{vip,svip}   (tetap di repo, tapi TIDAK ikut APK)
#  - VipAssets.kt memuat aset lewat URL + cache (Coil dibatasi 100MB, bawaannya bisa 250MB)
#  - lion.png & tiger.png (5MB) -> WebP (±0.9MB)
#  - Workflow mencetak ukuran APK + 12 file terbesar di dalamnya
# Jalankan di root repo:
#   bash pasang-aset-remote.sh                 (URL ditebak otomatis dari git remote origin)
#   bash pasang-aset-remote.sh https://.../remote-assets/   (kalau mau host lain)
# SYARAT: repo GitHub harus PUBLIC supaya aset bisa diunduh app.
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
A="app/src/main/assets"
R="app/src/main/res/drawable-nodpi"
[ -f "$D/VipAssets.kt" ] || { echo "❌ Jalankan di root repo Hayu-android"; exit 1; }

# --- URL hosting ---
BASE="$1"
if [ -z "$BASE" ]; then
  REMOTE="$(git remote get-url origin 2>/dev/null || true)"
  SLUG="$(echo "$REMOTE" | sed -E 's#^(https?://([^@/]*@)?github\.com/|git@github\.com:)##; s#\.git$##; s#/$##')"
  case "$SLUG" in
    */*) BASE="https://cdn.jsdelivr.net/gh/$SLUG@main/remote-assets/" ;;
  esac
fi
[ -n "$BASE" ] || { echo "❌ URL GitHub tidak terbaca. Jalankan: bash pasang-aset-remote.sh https://cdn.jsdelivr.net/gh/USER/REPO@main/remote-assets/"; exit 1; }
case "$BASE" in */) ;; *) BASE="$BASE/" ;; esac
echo "URL aset: $BASE"

T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"

BK="$HOME/.hayu-backup-remote-$(date +%H%M%S)"
mkdir -p "$BK"
for f in "$D/VipAssets.kt" "$D/HayuApp.kt" "$D/SvgaPlayer.kt" ".github/workflows/build-apk.yml"; do
  [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
done

# --- 1. pindahkan aset (bukan salin: tidak makan ruang 2x) ---
SIZE_BEFORE="$(du -sh app/src/main 2>/dev/null | cut -f1)"
mkdir -p remote-assets
for d in vip svip; do
  if [ -d "$A/$d" ]; then
    rm -rf "remote-assets/$d"
    mv "$A/$d" "remote-assets/$d"
    echo "  dipindah  $A/$d -> remote-assets/$d"
  fi
done
[ -d remote-assets/vip ] || [ -d remote-assets/svip ] || { echo "❌ Folder aset tidak ditemukan"; exit 1; }
mkdir -p "$A"
(cd remote-assets && find vip svip -type f 2>/dev/null | sort) > "$A/remote_index.txt"
echo "  daftar    $A/remote_index.txt ($(wc -l < "$A/remote_index.txt") file)"

# --- 2. kode baru ---
cp "$T/new/$D/VipAssets.kt" "$D/VipAssets.kt"
cp "$T/new/$D/HayuApp.kt" "$D/HayuApp.kt"
sed -i "s#__BASE_URL__#$BASE#" "$D/VipAssets.kt"
grep -q "__BASE_URL__" "$D/VipAssets.kt" && { echo "❌ Gagal mengisi URL"; exit 1; }
echo "  dipasang  $D/VipAssets.kt, HayuApp.kt"

# --- 3. SvgaPlayer: asset:// -> URL online ---
S="$D/SvgaPlayer.kt"
if grep -q "decodeFromAssets" "$S"; then
  sed -i 's#parser.decodeFromAssets(url.removePrefix(VipAssets.PREFIX), completion)#parser.decodeFromURL(URL(VipAssets.url(url.removePrefix(VipAssets.PREFIX))), completion)#' "$S"
  grep -q "VipAssets.url(" "$S" || { echo "❌ Gagal mengubah $S"; exit 1; }
  echo "  DIPERBAIKI $S"
else
  echo "  ok         $S"
fi

# --- 4. lion & tiger -> webp ---
for n in lion tiger; do
  cp "$T/new/$R/$n.webp" "$R/$n.webp"
  rm -f "$R/$n.png"
done
echo "  lion/tiger -> webp"

# --- 5. workflow: cetak ukuran APK ---
WF=".github/workflows/build-apk.yml"
if [ -f "$WF" ] && ! grep -q "Ukuran APK" "$WF"; then
  : > "$WF.new"
  while IFS= read -r line || [ -n "$line" ]; do
    case "$line" in
      "      - name: Upload APK"*)
        printf '%s\n' "      - name: Ukuran APK" "        run: |" "          ls -lh app/build/outputs/apk/debug/app-debug.apk" "          unzip -l app/build/outputs/apk/debug/app-debug.apk | sort -n -r | head -12" "" >> "$WF.new" ;;
    esac
    printf '%s\n' "$line" >> "$WF.new"
  done < "$WF"
  mv "$WF.new" "$WF"
  echo "  workflow  + langkah Ukuran APK"
fi
rm -rf "$T"

echo ""
echo "✅ Selesai. app/src/main: $SIZE_BEFORE -> $(du -sh app/src/main | cut -f1). Backup kode: $BK"
echo "Lanjut (PENTING: push dulu supaya aset online ada sebelum APK dipakai):"
echo "  git add -A && git commit -m 'aset VIP/SVIP dipindah online' && git push"
echo "Cek aset sudah online (tunggu ±1-5 menit setelah push):"
echo "  ${BASE}vip/hero_arch.webp"
